import 'package:jaspr/client.dart';
import 'package:unibox_example_jaspr/main.dart';

/// The browser half of the example.
///
/// A static export writes one document per destination, so the runtime asks the
/// browser which document it is on rather than being compiled twice: the sign-up
/// document starts with the dialog open, and a runtime that opened it closed would
/// undo the state the document arrived in.
///
/// `tool/site.sh` compiles this file to `main.client.js` beside the pages. It is
/// written by hand rather than generated by `jaspr_builder` because the whole page
/// is one component: no `@client` marker has to be matched against a server tree,
/// so the entrypoint is three lines of host code.
void main() {
  runApp(buildExampleRoot(openSignup: Uri.base.path.endsWith('/signup/')));
}
